pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Deploy a reentrant attacker that calls withdrawReward again during the first call's external call.
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Give the attacker the required ETH to cover the bonuses.
        vm.deal(address(attacker), 1 ether);

        // The attacker triggers the reentrancy by calling getFirstWithdrawalBonus on itself.
        attacker.attack();

        // After the attack completes, check the invariant on the original contract.
        // The rule: after any finished sequence, rewardsForA for the attacker must be zero.
        // Because rewardsForA is private, we observe it indirectly via a second withdrawal attempt.
        // If rewardsForA[attacker] > 0, a second withdrawReward (called directly on c) would send ETH.
        uint256 balBefore = address(attacker).balance;
        vm.prank(address(attacker));
        try c.withdrawReward(address(attacker)) {} catch {}
        uint256 balAfter = address(attacker).balance;

        // If the invariant holds (rewardsForA == 0), no extra ETH is transferred.
        // If the mutant leaves stale value, a second withdrawal drains more ETH.
        assertTrue(balAfter == balBefore, "rewardsForA was not zero after attack");
    }
}

contract ReentrantAttacker {
    C public target;
    bool private attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack() external payable {
        target.getFirstWithdrawalBonus(address(this));
    }

    receive() external payable {
        if (!attacking) {
            attacking = true;
            // Re-enter withdrawReward while rewardsForA[this] is still non-zero in the mutant.
            target.withdrawReward(address(this));
            attacking = false;
        }
    }
}

