pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        // Adversarial deploy: a reentrant attacker that calls withdrawReward again from its receive
        Reenterer reenterer = new Reenterer(address(c));
        vm.deal(address(c), 1000 ether);
        // We need rewardsForA > 0; getFirstWithdrawalBonus will set it and call withdrawReward
        // But fuzzer gives recipient; we must ensure it's the attacker
        vm.prank(address(reenterer));
        c.getFirstWithdrawalBonus(address(reenterer));
        uint256 balanceBefore = address(c).balance;
        (bool ok, ) = address(reenterer).call(abi.encodeWithSignature("attack()"));
        // attack() triggers a second withdrawReward via reentrancy; if reentrancy succeeds, more Ether was drained
        // The universal rule: after the attack (which follows getFirstWithdrawalBonus), c's balance must be at most balanceBefore minus the total legitimate rewards
        // Since getFirstWithdrawalBonus awards 100 wei once, the max legitimate drain is 100 wei per successful withdrawal.
        uint256 totalRewards = 100; // from claimedBonus false -> rewardsForA[attacker] +=100
        // The attack attempts to call withdrawReward again; under correct C, reentrancy fails due to _locked modifier -> only 100 wei drained.
        // Under mutant, rewardsForA not zeroed before external call, so reentrant call sees old balance and can drain additional 100.
        assertTrue(address(c).balance >= balanceBefore - 2*totalRewards);
    }
}
contract Reenterer {
    C target;
    bool attackActive;
    uint256 count;
    constructor(address _target) { target = C(_target); }
    receive() external payable {
        if (attackActive && count < 1) {
            count++;
            target.withdrawReward(address(this));
        }
    }
    function attack() external {
        attackActive = true;
        count = 0;
        target.withdrawReward(address(this));
        attackActive = false;
    }
}

